insert into public.market_needs (id,dataset,title,target_user,problem,current_solution,desired_outcome,evidence_note) values ('d985f367-83d7-5524-b9ce-5f95e53d61a7','example','設備監視センサーの保守負担','工場の設備保全担当','配線や電池交換が、監視点の増設・運用の負担になっている可能性','有線給電・電池・定期巡回','交換作業を減らし、必要な監視点を増やせること','議論用の仮説。市場調査・顧客ヒアリングでの確認は未実施。');
insert into public.market_needs (id,dataset,title,target_user,problem,current_solution,desired_outcome,evidence_note) values ('6acc6d5d-1771-5cca-b21c-9a5740850cc2','example','透明部材の曇り・結露対策','光学機器・屋外機器の利用者','視認性を保ちたい一方、加熱部材の透明性・形状・耐久性を両立しにくい可能性','既存の透明導電膜・防曇処理','対象の形状で必要な視認性と防曇性能を両立すること','議論用の仮説。市場調査・顧客ヒアリングでの確認は未実施。');
insert into public.market_needs (id,dataset,title,target_user,problem,current_solution,desired_outcome,evidence_note) values ('af62e3af-4595-5f08-8526-599507b3669b','example','切削加工の工具交換判断','加工工場の生産・品質担当','工具摩耗を十分に把握できず、早すぎる交換や加工不良が生じている可能性','経験則・定期交換・既存センサー','加工品質を維持しながら交換時期の判断を改善すること','議論用の仮説。市場調査・顧客ヒアリングでの確認は未実施。');
insert into public.market_needs (id,dataset,title,target_user,problem,current_solution,desired_outcome,evidence_note) values ('98e1eaac-d834-5f1e-b3ff-aa5b52aa53be','example','極低温環境の維持・運用','量子機器の開発・運用担当','必要な低温と安定性を、装置の大きさ・運用条件の中で実現する課題がある可能性','既存の冷凍機・冷却構成','用途別に必要な到達温度・冷却能力・安定性を満たすこと','議論用の仮説。市場調査・顧客ヒアリングでの確認は未実施。');
insert into public.company_needs (id,dataset,market_need_id,title,company_name,business_area,strengths,strategic_intent,missing_capability,constraints,evidence_note) values ('7a1d48bd-01ac-5a66-a741-a7e454e186a9','example','d985f367-83d7-5524-b9ce-5f95e53d61a7','後付けセンサーの給電を省力化','仮の企業像｜産業用センサーメーカー','産業用センサーの開発・販売','低消費電力回路・無線通信・顧客接点','設置・保守の負担が小さい監視機器を増やす','温度差が変動する現場での発電・蓄電の成立条件','消費電力、設置面、温度差、寿命、単価は未確認','仮の企業像。実在企業の意向・予算・発言を表すものではない。');
insert into public.company_needs (id,dataset,market_need_id,title,company_name,business_area,strengths,strategic_intent,missing_capability,constraints,evidence_note) values ('ad83ef62-bca6-5054-ac6e-a950b85a342a','example','d985f367-83d7-5524-b9ce-5f95e53d61a7','配線困難な設備の監視点を増設','仮の企業像｜設備保全サービス会社','工場設備の保全サービス','現場作業・設置調整・運用データ','監視サービスの対象設備を広げる','実設備への取り付け方法と、保守負担が下がる条件','既設設備への施工、安全性、運用負担は未確認','仮の企業像。実在企業の意向・予算・発言を表すものではない。');
insert into public.company_needs (id,dataset,market_need_id,title,company_name,business_area,strengths,strategic_intent,missing_capability,constraints,evidence_note) values ('72deb789-be33-5c2d-b59e-7005ce5995f4','example','6acc6d5d-1771-5cca-b21c-9a5740850cc2','曲面の透明部材へ加熱機能を付加','仮の企業像｜光学部材メーカー','透明フィルム・光学部材','成形・積層・表面処理','透明部材へ防曇等の機能を追加する','必要な透明性・抵抗・耐久性を同時に満たす導電層','対象部材、透過率、温度、耐候性、コストは未確認','仮の企業像。実在企業の意向・予算・発言を表すものではない。');
insert into public.company_needs (id,dataset,market_need_id,title,company_name,business_area,strengths,strategic_intent,missing_capability,constraints,evidence_note) values ('49a4eb43-1253-5d65-857a-c41e7ef2f491','example','af62e3af-4595-5f08-8526-599507b3669b','工具摩耗の判断支援を製品化','仮の企業像｜工作機械・工具メーカー','加工機・工具の開発・販売','加工条件・顧客現場・装置への組込み','機械・工具の付加価値と保守支援を強化する','実加工での画像取得と、摩耗を判別する学習・評価方法','切削液、切りくず、撮影条件、材種の差は未確認','仮の企業像。実在企業の意向・予算・発言を表すものではない。');
insert into public.company_needs (id,dataset,market_need_id,title,company_name,business_area,strengths,strategic_intent,missing_capability,constraints,evidence_note) values ('594a1edf-0765-5006-b037-70bbeac32b6c','example','98e1eaac-d834-5f1e-b3ff-aa5b52aa53be','用途に合う低温冷却構成を探索','仮の企業像｜低温機器メーカー','研究用低温装置','真空・低温設計・計測・装置統合','量子機器向けの冷却構成の選択肢を増やす','磁気冷凍を既存構成と組み合わせる際の成立条件','到達温度、熱負荷、磁場影響、冷却周期は未確認','仮の企業像。実在企業の意向・予算・発言を表すものではない。');
insert into public.company_needs (id,dataset,market_need_id,title,company_name,business_area,strengths,strategic_intent,missing_capability,constraints,evidence_note) values ('42285561-60ab-5d76-8642-e9a81978a8ad','example','af62e3af-4595-5f08-8526-599507b3669b','加工現場の導入条件を整理','仮の企業像｜加工受託会社','多品種の受託加工','加工工程・品質管理・現場運用','不良と工具交換に伴う損失を抑える','検出したい不良・摩耗と、導入できる計測方法の特定','対応工程・計測制約を聞いたうえでシーズを探索','仮の企業像。実在企業の意向・予算・発言を表すものではない。');
insert into public.seed_need_matches (id,dataset,company_need_id,seed_id,rationale,research_question,experiment,success_criteria,funding_note,next_action) values ('6f8e727b-5e99-5ea6-86e1-d907ae551ec7','example','7a1d48bd-01ac-5a66-a741-a7e454e186a9','a1390f71-3d7d-4bbc-9016-ca25bc901c34','曲面に取り付ける熱電発電を、低消費電力センサーの給電へ利用する仮説','想定する温度差で、測定・通信に必要な電力を確保できるか','温度差を変えた発電試験とセンサーの間欠動作試験','必要電力と温度条件を企業と定義してから判定','費用負担者・予算・実施場所・契約条件は未確認','対象センサーの消費電力と現場の温度差を聞く');
insert into public.seed_need_matches (id,dataset,company_need_id,seed_id,rationale,research_question,experiment,success_criteria,funding_note,next_action) values ('f40868b4-39c2-5fc1-aba5-f5c7de2db18e','example','ad83ef62-bca6-5054-ac6e-a950b85a342a','a1390f71-3d7d-4bbc-9016-ca25bc901c34','同じ熱電シーズを、保全サービスの設置・運用条件から評価する仮説','取り付けと保守を含めて、有線・電池より負担が減るか','候補設備で取り付け方法・発電の変動・交換作業を比較','保守工数、安全条件、稼働条件を企業と定義してから判定','費用負担者・予算・実施場所・契約条件は未確認','監視できていない設備と、配線・交換の制約を聞く');
insert into public.seed_need_matches (id,dataset,company_need_id,seed_id,rationale,research_question,experiment,success_criteria,funding_note,next_action) values ('7c44d83b-272c-54f2-8b9d-2753bd0c0e9b','example','72deb789-be33-5c2d-b59e-7005ce5995f4','fc966b38-8411-40bb-a91f-7cee9e4bd3a2','透明フレキシブル導電膜を、曲面の加熱・防曇へ展開する仮説','導電性に加え、加熱均一性・透明性・耐久性を満たせるか','対象基材での加熱・透過・曲げ・環境耐久試験','用途の透過率・温度分布・耐久要件を確認してから判定','費用負担者・予算・実施場所・契約条件は未確認','対象製品・既存材料・採用要件を聞く');
insert into public.seed_need_matches (id,dataset,company_need_id,seed_id,rationale,research_question,experiment,success_criteria,funding_note,next_action) values ('bf3ab6a2-ef6c-5959-bc6e-7ecded7278d0','example','49a4eb43-1253-5d65-857a-c41e7ef2f491','e4a10031-8299-5ab3-8595-63ce834dc109','画像とAIの研究を、工具交換判断の支援へ展開する仮説','実加工の条件差の中で、必要な摩耗状態を判別できるか','対象工程の撮影と摩耗の実測を対応させ、未学習条件で評価','誤検知・見逃し・作業負担の許容値を企業と定義','費用負担者・予算・実施場所・契約条件は未確認','見たい摩耗と撮影可能な場所・条件を聞く');
insert into public.seed_need_matches (id,dataset,company_need_id,seed_id,rationale,research_question,experiment,success_criteria,funding_note,next_action) values ('d40e5a47-6451-5fb2-8fe2-87b642a89214','example','594a1edf-0765-5006-b037-70bbeac32b6c','25f814a6-c151-098e-651f-6f23288fd829','磁気冷凍を、特定の量子機器に必要な低温環境へ適用する仮説','対象機器の温度・熱負荷・磁場影響の条件に適合するか','対象条件の整理後、冷却構成と評価系を研究者と検討','用途別の到達温度・冷却能力・安定性を合意してから判定','費用負担者・予算・実施場所・契約条件は未確認','必要温度帯・熱負荷・磁場制約を聞く');
